package com.bananalab.lite;
import java.util.*;import java.util.regex.*;import org.json.*;
/** Typed, compositional, bounded IR. Not unrestricted Java generation. */
final class ProgramPlan{
 final String family;final JSONArray steps;
 ProgramPlan(String family,JSONArray steps)throws Exception{this.family=family;this.steps=new JSONArray(steps.toString());validate();}
 JSONObject json()throws Exception{return new JSONObject().put("version",1).put("family",family).put("steps",steps);}
 static ProgramPlan read(JSONObject data)throws Exception{RuntimeProgram.keys(data,"version","family","steps");if(data.getInt("version")!=1)throw new IllegalArgumentException("Programa incompatible.");return new ProgramPlan(data.getString("family"),data.getJSONArray("steps"));}
 static final String ARRAY="sort|descending|unique|abs|square|add|multiply|gt|lt|positive|negative|even|odd|sum|count|min|max|map_expr|filter_expr",TEXT="trim|lower|upper|reverse|letters|digits|no_spaces";
 void validate()throws Exception{if(!family.matches("array|text")||steps.length()<1||steps.length()>12)throw new IllegalArgumentException("Un programa admite de1 a12 pasos de listas o texto.");boolean scalar=false;for(int i=0;i<steps.length();i++){JSONObject row=steps.getJSONObject(i);String op=row.getString("op");if(op.endsWith("_expr")){RuntimeProgram.keys(row,"op","value","expr");Formula.parse(row.getString("expr"),op.equals("filter_expr"));}else RuntimeProgram.keys(row,"op","value");if(scalar||!op.matches(family.equals("array")?ARRAY:TEXT))throw new IllegalArgumentException("Tipos de pasos incompatibles.");int value=row.optInt("value",0);if(Math.abs((long)value)>1000||!op.matches("add|multiply|gt|lt")&&value!=0)throw new IllegalArgumentException("Constante fuera del contrato.");scalar=op.matches("sum|count|min|max");}}
 static String normalize(String input){return Knowledge.normalize(input).replaceAll("[^a-z0-9 ;\\-]"," ").replaceAll("\\s+"," ").trim();}
 static ProgramPlan request(String request)throws Exception{String original=Knowledge.normalize(request).trim();if(original.matches("(?s).*(?:transforma|transforme|conserva|conserve) cada (?:numero|elemento).*")){JSONArray rows=new JSONArray();for(String clause:original.split("\\s*(?:;|\\by despues\\b)\\s*",-1)){java.util.regex.Matcher formula=java.util.regex.Pattern.compile("^(transforma|transforme|conserva|conserve) cada (?:numero|elemento) (?:en|si|cuando) (.+)$").matcher(clause.trim());if(formula.matches()){boolean filter=formula.group(1).startsWith("conserv");String expr=Formula.natural(formula.group(2));Formula.parse(expr,filter);rows.put(new JSONObject().put("op",filter?"filter_expr":"map_expr").put("value",0).put("expr",expr));}else{if(clause.matches("(?s).*(?:transforma|transforme|conserva|conserve) cada (?:numero|elemento).*"))throw new IllegalArgumentException("Formula incompleta");ProgramPlan tail=request(clause);if(!tail.family.equals("array"))throw new IllegalArgumentException("Formula de numeros incompatible con texto");for(int i=0;i<tail.steps.length();i++)rows.put(tail.steps.getJSONObject(i));}}return new ProgramPlan("array",rows);}String q=normalize(request).replaceAll("\\b(?:ordene|ordenar)\\b","ordena").replaceAll("\\b(?:quite|elimine|eliminar|quitar)\\b","quita").replaceAll("\\b(?:sume|sumar)\\b","suma").replaceAll("\\b(?:multiplique|multiplicar)\\b","multiplica").replaceAll("\\b(?:recorte|recortar)\\b","recorta").replaceAll("\\b(?:invierta|invertir)\\b","invierte");if(q.length()>900)throw new IllegalArgumentException("Pedido demasiado largo.");String family=q.matches("(?s).*\\b(?:texto|cadena|palabra|minusculas|mayusculas|espacios)\\b.*")?"text":"array";String[] parts=q.split("\\s*(?:;|\\by despues\\b|\\by\\b)\\s*",-1);JSONArray steps=new JSONArray();for(String part:parts){String s=part.replaceAll("\\b(?:la|el|una|un|los|las|de|del|en|a|al|que|para|despues|luego|lista|arreglo|numeros|valores|texto|cadena|palabra)\\b"," ").replaceAll("\\s+"," ").trim();String op="";int value=0;
 if(s.matches("ordena(?: ascendente| menor mayor)?"))op="sort";else if(s.matches("ordena (?:descendente|mayor menor)"))op="descending";else if(s.matches("quita duplicados|sin duplicados"))op="unique";else if(s.matches("valor absoluto|valores absolutos|absolutos"))op="abs";else if(s.matches("eleva cuadrado|cuadrados"))op="square";else if(s.matches("suma|cuenta|minimo|maximo"))op=s.equals("suma")?"sum":s.equals("cuenta")?"count":s.equals("minimo")?"min":"max";else if(s.matches("(?:filtra |solo )?(positivos|negativos|pares|impares)"))op=s.endsWith("positivos")?"positive":s.endsWith("negativos")?"negative":s.endsWith("impares")?"odd":"even";else if(s.matches("recorta(?: extremos)?|trim"))op="trim";else if(s.equals("minusculas"))op="lower";else if(s.equals("mayusculas"))op="upper";else if(s.equals("invierte"))op="reverse";else if(s.matches("(?:solo |filtra )?letras"))op="letters";else if(s.matches("(?:solo |filtra )?digitos"))op="digits";else if(s.matches("quita espacios|sin espacios"))op="no_spaces";else{Matcher m=Pattern.compile("(suma|multiplica|mayores|menores)(?: por| cada numero| cada valor| cada elemento| cada)? (-?[0-9]{1,4})").matcher(s);if(m.matches()){op=m.group(1).equals("suma")?"add":m.group(1).equals("multiplica")?"multiply":m.group(1).equals("mayores")?"gt":"lt";value=Integer.parseInt(m.group(2));}}
 if(op.isEmpty())throw new IllegalArgumentException("No entendí el paso completo: "+part+". No preparé un programa parcial.");steps.put(new JSONObject().put("op",op).put("value",value));}return new ProgramPlan(family,steps);}
 String body(JSONObject row)throws Exception{String op=row.getString("op");int v=row.optInt("value",0);if(family.equals("text")){String prefix="String s=ProgramSupport.text(input);";if(op.equals("trim"))return prefix+"return s.trim();";if(op.equals("lower"))return prefix+"return s.toLowerCase(java.util.Locale.ROOT);";if(op.equals("upper"))return prefix+"return s.toUpperCase(java.util.Locale.ROOT);";if(op.equals("reverse"))return prefix+"return new StringBuilder(s).reverse().toString();";return prefix+"StringBuilder r=new StringBuilder();for(int i=0;i<s.length();i++){char c=s.charAt(i);if("+(op.equals("letters")?"Character.isLetter(c)":op.equals("digits")?"Character.isDigit(c)":"!Character.isWhitespace(c)")+")r.append(c);}return r.toString();";}
 String b="int[] a=ProgramSupport.numbers(input);";if(op.endsWith("_expr")){String expression=Formula.parse(row.getString("expr"),op.equals("filter_expr")).java();if(op.equals("map_expr"))return b+"for(int i=0;i<a.length;i++){int v="+expression+";if(v<-1000||v>1000)throw new IllegalArgumentException();a[i]=v;}return ProgramSupport.csv(a,a.length);";return b+"int n=0;for(int i=0;i<a.length;i++)if("+expression+")a[n++]=a[i];return ProgramSupport.csv(a,n);";}if(op.equals("sort")||op.equals("descending")){b+="for(int i=1;i<a.length;i++){int n=a[i],j=i-1;while(j>=0&&a[j]"+(op.equals("sort")?">":"<")+"n){a[j+1]=a[j];j--;}a[j+1]=n;}return ProgramSupport.csv(a,a.length);";return b;}
 if(op.equals("unique"))return b+"int n=0;for(int i=0;i<a.length;i++){boolean seen=false;for(int j=0;j<n;j++)if(a[j]==a[i])seen=true;if(!seen)a[n++]=a[i];}return ProgramSupport.csv(a,n);";
 if(op.matches("abs|square|add|multiply"))return b+"for(int i=0;i<a.length;i++){long n="+(op.equals("abs")?"Math.abs((long)a[i])":op.equals("square")?"(long)a[i]*a[i]":op.equals("add")?"(long)a[i]+("+v+")":"(long)a[i]*("+v+")")+";if(n<-1000||n>1000)throw new IllegalArgumentException(\"Paso fuera del rango-1000..1000\");a[i]=(int)n;}return ProgramSupport.csv(a,a.length);";
 if(op.matches("sum|count|min|max")){if(op.equals("count"))return b+"return Integer.toString(a.length);";return b+"int r="+(op.equals("sum")?"0":"a.length==0?0:a[0]")+";for(int i=0;i<a.length;i++){"+(op.equals("sum")?"r+=a[i];":op.equals("min")?"if(a[i]<r)r=a[i];":"if(a[i]>r)r=a[i];")+"}return Integer.toString(r);";}
 String predicate=op.equals("gt")?"a[i]>"+v:op.equals("lt")?"a[i]<"+v:op.equals("positive")?"a[i]>0":op.equals("negative")?"a[i]<0":op.equals("even")?"a[i]%2==0":"a[i]%2!=0";return b+"int n=0;for(int i=0;i<a.length;i++)if("+predicate+")a[n++]=a[i];return ProgramSupport.csv(a,n);";}
 String kernel()throws Exception{StringBuilder s=new StringBuilder("package com.bananalab.lite;final class ProgramKernel{static String apply(String input){String s=input;");for(int i=0;i<steps.length();i++)s.append("s=step").append(i).append("(s);");s.append("return s;}");for(int i=0;i<12;i++)s.append("static String step").append(i).append("(String input){").append(i<steps.length()?body(steps.getJSONObject(i)):"return input;").append("}");return s.append('}').toString();}
 Map<String,String> core()throws Exception{Map<String,String> out=new LinkedHashMap<>();String token=JavaMethodEditor.hash(json().toString()).substring(0,20);out.put("JavaAlgorithm.java","package com.bananalab.lite;final class JavaAlgorithm{static String process(String input){return ProgramKernel.apply(input);}static String kind(){return \"pipeline\";}static String version(){return \""+token+"\";}static int[] numbers(String input){return MethodProgram.numbers(input);}}");out.put("ProgramKernel.java",kernel());return out;}
 Map<String,String> candidate()throws Exception{Map<String,String> out=new LinkedHashMap<>();out.put("BananaBehavior.java",JavaPatchPolicy.BASE);out.put("FormulaMath.java",formulaMathSource());out.put("ProgramKernel.java",kernel().replace("package com.bananalab.lite;final class ProgramKernel","package com.bananalab.patch;public final class ProgramKernel").replace("static String apply(","public static String apply("));out.put("ProgramSupport.java","package com.bananalab.patch;final class ProgramSupport{static int[] numbers(String input){"+MethodProgram.parser()+"}static String csv(int[] a,int n){StringBuilder s=new StringBuilder();for(int i=0;i<n;i++){if(i>0)s.append(',');s.append(a[i]);}return s.toString();}static String text(String input){if(input.length()>128)throw new IllegalArgumentException();return input;}}");return out;}
 static String formulaMathSource(){return "package com.bananalab.patch;final class FormulaMath{static int check(long n){if(n < -1000000 || n > 1000000)throw new IllegalArgumentException();return (int)n;}static int add(int a,int b){return check((long)a+b);}static int sub(int a,int b){return check((long)a-b);}static int mul(int a,int b){return check((long)a*b);}static int div(int a,int b){if(b==0)throw new IllegalArgumentException();return check((long)a/b);}static int mod(int a,int b){if(b==0)throw new IllegalArgumentException();return a%b;}static int neg(int a){return check(-(long)a);}static int abs(int a){return check(Math.abs((long)a));}}";}
 String oracle(String input)throws Exception{String value=input;for(int i=0;i<steps.length();i++){JSONObject row=steps.getJSONObject(i);String op=row.getString("op");int n=row.optInt("value",0);if(family.equals("text")){if(value.length()>128)throw new IllegalArgumentException();if(op.equals("trim"))value=value.trim();else if(op.equals("lower"))value=value.toLowerCase(Locale.ROOT);else if(op.equals("upper"))value=value.toUpperCase(Locale.ROOT);else if(op.equals("reverse"))value=new StringBuilder(value).reverse().toString();else{StringBuilder b=new StringBuilder();for(char ch:value.toCharArray())if(op.equals("letters")?Character.isLetter(ch):op.equals("digits")?Character.isDigit(ch):!Character.isWhitespace(ch))b.append(ch);value=b.toString();}}else{List<Integer> list=new ArrayList<>();for(int x:MethodProgram.numbers(value))list.add(x);if(op.equals("sort"))Collections.sort(list);else if(op.equals("descending"))Collections.sort(list,Collections.reverseOrder());else if(op.equals("unique"))list=new ArrayList<>(new LinkedHashSet<>(list));else if(op.matches("sum|count|min|max")){int result=op.equals("count")?list.size():op.equals("min")?(list.isEmpty()?0:Collections.min(list)):op.equals("max")?(list.isEmpty()?0:Collections.max(list)):0;if(op.equals("sum"))for(int x:list)result+=x;value=""+result;continue;}else{List<Integer> next=new ArrayList<>();for(int x:list){if(op.endsWith("_expr")){long z=Formula.parse(row.getString("expr"),op.equals("filter_expr")).eval(x);if(op.equals("filter_expr")){if(z!=0)next.add(x);}else{if(z < -1000 || z > 1000)throw new IllegalArgumentException();next.add((int)z);}}else if(op.matches("abs|square|add|multiply")){long z=op.equals("abs")?Math.abs((long)x):op.equals("square")?(long)x*x:op.equals("add")?(long)x+n:(long)x*n;if(z<-1000||z>1000)throw new IllegalArgumentException();next.add((int)z);}else if(op.equals("gt")?x>n:op.equals("lt")?x<n:op.equals("positive")?x>0:op.equals("negative")?x<0:op.equals("even")?(x&1)==0:(x&1)!=0)next.add(x);}list=next;}StringBuilder b=new StringBuilder();for(int x:list){if(b.length()>0)b.append(',');b.append(x);}value=b.toString();}}return value;}
}
